insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('909b7cad-f6c4-4435-b57f-e88611f1b455', '4d13194f-4502-47bb-a540-5a677e67d647', $$inleiding: graaiflatie en de stijging van omzet en resultaat van Ahold Delhaize$$,
   $$bedrijfseconomie-vwo-2025-i-ahold-delhaize-context1.png$$,
   $$Eind 2022 is het nieuwe woord “graaiflatie” opgenomen in de woordenboeken. Graaiflatie betekent dat bedrijven de verkoopprijzen meer verhogen dan de toegenomen kosten. Graaiflatie zorgt voor een toename van de resultaatmarge. Ook bij Ahold Delhaize, het moederbedrijf van onder andere Albert Heijn en Gall & Gall, zou volgens sommige media sprake zijn van graaiflatie.
Ahold Delhaize boekte in 2022 een stijging van de omzet en het resultaat ten opzichte van 2021:$$, 'inline'),
  ('700678ec-60ad-431a-9798-1c14bf249dcc', '4d13194f-4502-47bb-a540-5a677e67d647', $$financieel overzicht Ahold Delhaize 2022 en 2021 (getallen in miljoen euro's)$$,
   $$bedrijfseconomie-vwo-2025-i-ahold-delhaize-context2.png$$,
