  ('c8693067-237b-48f7-abcc-45cd864b802b', 'f0f7beba-7efc-48e2-a388-0f1812f56443', $$krediettermijn debiteuren verkort van 4 naar 2 weken; 80% op rekening$$,
   $$bedrijfseconomie-vwo-2025-i-de-kleine-bv-context8.png$$,
   $$De Kleine heeft op 1 januari 2024, de eerste dag van week 1, de krediettermijn voor debiteuren verkort van 4 weken naar 2 weken. Afnemers maken volledig gebruik van de krediettermijn. Hierdoor verandert de omvang van de balanspost Debiteuren. De verkopen zijn voor 80% op rekening.$$, 'inline'),
  ('4118c71f-5e84-4f00-9281-90587186f1f0', 'd60db63f-c1b3-46fa-acf1-4a2b3e47d5f7', $$Klaas Dane erft € 150.000 van zijn neef Thom$$,
   $$bedrijfseconomie-vwo-2025-i-klaas-dane-context1.png$$,
   $$Klaas Dane heeft in februari 2025 van de notaris bericht gekregen dat hij € 150.000 heeft geërfd van zijn neef Thom. Op de site van de Belastingdienst ziet hij onderstaande gegevens over de te betalen erfbelasting.$$, 'inline'),
  ('e552f0af-2524-41b3-b80e-513ed21887ce', 'd60db63f-c1b3-46fa-acf1-4a2b3e47d5f7', $$vrijstellingen en tarieven erf- en schenkbelasting$$,
